import{_ as t,a}from"./chunks/px4_sitl_overview.XgOTfz33.js";import{_ as i,o as s,c as n,al as o}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"Симуляція","description":"","frontmatter":{},"headers":[],"relativePath":"uk/simulation/index.md","filePath":"uk/simulation/index.md"}'),r={name:"uk/simulation/index.md"};function l(h,e,p,d,c,m){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="симуляція" tabindex="-1">Симуляція <a class="header-anchor" href="#симуляція" aria-label="Permalink to &quot;Симуляція&quot;">​</a></h1><p>Симулятори дозволяють польотному коду PX4 керувати комп&#39;ютерно змодельованим апаратом у змодельованому &quot;світі&quot;. You can interact with this vehicle just as you might with a real vehicle, using <em>QGroundControl</em>, an offboard API, or a radio controller/gamepad.</p><p>PX4 supports both <em>Software In the Loop (SITL)</em> simulation, where the flight stack runs on computer (either the same computer or another computer on the same network) and <em>Hardware In the Loop (HITL)</em> simulation using a simulation firmware on a real flight controller board.</p><p>Інформація про доступні тренажери та способи їх налаштування наведена в наступному розділі. The other sections provide general information about how the simulator works, and are not required to <em>use</em> the simulators.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Simulation is a quick, easy, and most importantly, <em>safe</em> way to test changes to PX4 code before attempting to fly in the real world. Це також хороший спосіб почати літати з PX4, якщо у вас ще немає апарату для експериментів.</p></div><h2 id="підтримувані-симулятори" tabindex="-1">Підтримувані симулятори <a class="header-anchor" href="#підтримувані-симулятори" aria-label="Permalink to &quot;Підтримувані симулятори&quot;">​</a></h2><p>Наступні симулятори підтримуються основною командою розробників PX4.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Gazebo Classic is being downgraded to <a href="./../simulation/community_supported_simulators">community supported</a> and is no longer recommended as the default simulation solution. Use <a href="./../sim_gazebo_gz/">Gazebo</a> (formerly Gazebo Ignition) for new projects. If you have an older workflow that does not yet work in newer Gazebo, Gazebo Classic remains available but will not receive core team maintenance going forward. See <a href="https://github.com/PX4/PX4-Autopilot/issues/23602" target="_blank" rel="noreferrer">PX4-Autopilot#23602</a> for the deprecation timeline and migration status.</p></div><table tabindex="0"><thead><tr><th>Симулятор</th><th>Опис</th></tr></thead><tbody><tr><td><a href="./../sim_gazebo_gz/">Gazebo</a></td><td>Gazebo supersedes <a href="./../sim_gazebo_classic/">Gazebo Classic</a>, featuring more advanced rendering, physics and sensor models. It is the only version of Gazebo available from Ubuntu Linux 22.04<br><br>A powerful 3D simulation environment that is particularly suitable for testing object-avoidance and computer vision. Він також може бути використаний для <a href="./../simulation/multi-vehicle-simulation">multi-vehicle simulation</a> і зазвичай використовується з <a href="./../simulation/ros_interface">ROS</a>, набором інструментів для автоматизації керування апаратами. <br><br><strong>Supported Vehicles:</strong> Quad, VTOL (Standard, Tailsitter, Tiltroter), Plane, Rovers</td></tr><tr><td><a href="./../sim_sih/">SIH</a></td><td>A lightweight, headless simulator that runs physics directly inside PX4 as a C++ module (no external dependencies). Headless by default for fastest iteration. Supports ROS 2 via uXRCE-DDS. Can also run on flight controller hardware (<code>SYS_HITL=2</code>).<br><br><strong>Supported Vehicles:</strong> Quad, Hex, Plane, Tailsitter, Standard VTOL, Rover</td></tr><tr><td><a href="./../sim_gazebo_classic/">Gazebo Classic</a></td><td>A powerful 3D simulation environment that is particularly suitable for testing object-avoidance and computer vision. It can also be used for <a href="./../simulation/multi-vehicle-simulation">multi-vehicle simulation</a> and is commonly used with <a href="./../simulation/ros_interface">ROS</a>, a collection of tools for automating vehicle control.<br><br><strong>Supported Vehicles:</strong> Quad (<a href="./../airframes/airframe_reference#copter_quadrotor_x_generic_quadcopter">Iris</a>), Hex (Typhoon H480), <a href="./../airframes/airframe_reference#vtol_standard_vtol_generic_standard_vtol">Generic Standard VTOL (QuadPlane)</a>, Tailsitter, Plane, Rover, Submarine</td></tr></tbody></table><p>There are also a number of <a href="./../simulation/community_supported_simulators">Community Supported Simulators</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To run PX4 SITL without setting up a build environment, <a href="./px4_sitl_prebuilt_packages">pre-built packages and containers</a> are available.</p></div><h3 id="simulator-comparison" tabindex="-1">Simulator Comparison <a class="header-anchor" href="#simulator-comparison" aria-label="Permalink to &quot;Simulator Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Характеристика</th><th>Gazebo</th><th>SIH</th></tr></thead><tbody><tr><td><strong>Default Mode</strong></td><td>GUI with 3D rendering</td><td>Headless (fastest iteration)</td></tr><tr><td><strong>3D Visualization</strong></td><td>Built-in (photorealistic)</td><td>Optional: QGC map or jMAVSim display-only</td></tr><tr><td><strong>Physics Engine</strong></td><td>External (gz-physics)</td><td>Internal (C++ module, uORB)</td></tr><tr><td><strong>External Dependencies</strong></td><td>Gazebo packages, rendering libs</td><td>None</td></tr><tr><td><strong>Vehicle Types</strong></td><td>Quad, VTOL, Plane, Rovers</td><td>Quad, Hex, Plane, Tailsitter, Std VTOL, Rover</td></tr><tr><td><strong>Multi-vehicle</strong></td><td>Yes (documented)</td><td>Yes (<a href="./../sim_sih/#multi-vehicle-simulation">multi-vehicle</a>)</td></tr><tr><td><strong>Sensor Simulation</strong></td><td>Camera, LiDAR, depth, IMU, GPS, baro, mag</td><td>IMU, GPS, baro, mag, airspeed</td></tr><tr><td><strong>Custom Worlds/Models</strong></td><td>Yes (SDF, large model library)</td><td>Ні</td></tr><tr><td><strong>ROS 2 Integration</strong></td><td>Yes (uXRCE-DDS)</td><td>Yes (uXRCE-DDS)</td></tr><tr><td><strong>Extensibility</strong></td><td>Plugins, custom sensors, environments</td><td>Modify C++ source, tune SIH_* parameters</td></tr><tr><td><strong>Community/Ecosystem</strong></td><td>Large Gazebo community, model repos</td><td>PX4-internal</td></tr><tr><td><strong>Faster-than-Realtime</strong></td><td>Так</td><td>Так</td></tr><tr><td><strong>Runs on FC Hardware</strong></td><td>Ні</td><td>Yes (SYS_HITL=2)</td></tr><tr><td><strong>macOS Apple Silicon</strong></td><td>Unstable (known issues)</td><td>Works natively</td></tr><tr><td><strong>Lockstep</strong></td><td>Так</td><td>Так</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For a detailed analysis of PX4 simulation user needs, priorities, and pain points, see the <a href="https://www.mcguirerobotics.com/px4_sim_research_report/" target="_blank" rel="noreferrer">PX4 Simulation Integration Survey Report</a> (K. McGuire, Dronecode Foundation, Dec 2025, 120 respondents).</p></div><h3 id="which-simulator-should-i-use" tabindex="-1">Which Simulator Should I Use? <a class="header-anchor" href="#which-simulator-should-i-use" aria-label="Permalink to &quot;Which Simulator Should I Use?&quot;">​</a></h3><ul><li><strong>Full-featured simulation with 3D rendering, custom worlds, camera/lidar sensors, or rich sensor ecosystems:</strong> Use <a href="./../sim_gazebo_gz/">Gazebo</a>. Largest ecosystem, custom models and plugins, photorealistic rendering, extensive sensor library, large community.</li><li><strong>Fast headless iteration, controls research, zero-dependency setup, or macOS:</strong> Use <a href="./../sim_sih/">SIH</a>. Runs entirely inside PX4 with no external dependencies, headless by default for maximum speed, physics parameters directly tunable via <code>SIH_*</code> params. Supports ROS 2 via uXRCE-DDS.</li><li><strong>Hardware integration testing without propellers:</strong> Use <a href="./../sim_sih/#sih-on-flight-controller-hardware">SIH on flight controller hardware</a> (<code>SYS_HITL=2</code>).</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>SIH is headless by default. For optional 3D visualization, you can use <a href="./../sim_sih/#visualization-optional">jMAVSim in display-only mode</a> or monitor the vehicle in QGroundControl&#39;s map view.</p></div><h2 id="симулятор-mavlink-api" tabindex="-1">Симулятор MAVLink API <a class="header-anchor" href="#симулятор-mavlink-api" aria-label="Permalink to &quot;Симулятор MAVLink API&quot;">​</a></h2><p>Most external simulators communicate with PX4 using the Simulator MAVLink API. Цей API визначає набір повідомлень MAVLink, які передають дані датчиків з модельованого світу в PX4 і повертають значення двигуна і приводу з польотного коду, які будуть застосовані до модельованого апарату. На зображенні нижче показано потік повідомлень.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>SIH does not use the MAVLink simulator API. It runs physics internally via uORB messages. Gazebo communicates with PX4 via gz_bridge (Gazebo transport), not MAVLink.</p></div><p><img src="'+t+'" alt="Simulator MAVLink API"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A SITL build of PX4 uses <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/simulation/simulator_mavlink/SimulatorMavlink.cpp" target="_blank" rel="noreferrer">SimulatorMavlink.cpp</a> to handle these messages while a hardware build in HIL mode uses <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_receiver.cpp" target="_blank" rel="noreferrer">mavlink_receiver.cpp</a>. Дані датчиків з симулятора записуються в теми PX4 uORB. Всі двигуни/приводи заблоковані, але внутрішнє програмне забезпечення повністю функціонує.</p></div><p>Повідомлення описані нижче (див. посилання для більш детальної інформації).</p><table tabindex="0"><thead><tr><th>Повідомлення</th><th>Напрямок</th><th>Опис</th></tr></thead><tbody><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_MODE_FLAG_HIL_ENABLED" target="_blank" rel="noreferrer">MAV_MODE:MAV_MODE_FLAG_HIL_ENABLED</a></td><td>NA</td><td>Прапорець режиму при використанні симуляції. Всі двигуни/приводи заблоковані, але внутрішнє програмне забезпечення повністю функціонує.</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_ACTUATOR_CONTROLS" target="_blank" rel="noreferrer">HIL_ACTUATOR_CONTROLS</a></td><td>PX4 -&gt; Sim</td><td>Виходи керування PX4 (до двигунів, приводів).</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_SENSOR" target="_blank" rel="noreferrer">HIL_SENSOR</a></td><td>Sim -&gt; PX4</td><td>Імітація показань IMU в одиницях СІ в рамі корпусу NED.</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_GPS" target="_blank" rel="noreferrer">HIL_GPS</a></td><td>Sim -&gt; PX4</td><td>Симульоване значення датчика GPS RAW.</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_OPTICAL_FLOW" target="_blank" rel="noreferrer">HIL_OPTICAL_FLOW</a></td><td>Sim -&gt; PX4</td><td>Імітація оптичного потоку від датчика потоку (наприклад, PX4FLOW або датчика оптичної миші)</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_STATE_QUATERNION" target="_blank" rel="noreferrer">HIL_STATE_QUATERNION</a></td><td>Sim -&gt; PX4</td><td>Містить фактичне &quot;змодельоване&quot; положення апарату, орієнтацію, швидкість і т.д. Це може бути записано в журнал і співставлено з оцінками PX4 для аналізу і діагностики (наприклад, перевірка того, наскільки добре оцінювач працює для зашумлених (імітованих) вхідних сигналів датчика).</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_RC_INPUTS_RAW" target="_blank" rel="noreferrer">HIL_RC_INPUTS_RAW</a></td><td>Sim -&gt; PX4</td><td>Отримані RAW-значення каналів РК.</td></tr></tbody></table><p>PX4 directly uses the <a href="https://gazebosim.org/docs/" target="_blank" rel="noreferrer">Gazebo API</a> to interface with <a href="./../sim_gazebo_gz/">Gazebo</a> and MAVlink is not required.</p><h2 id="порти-udp-px4-mavlink-за-замовчуванням" tabindex="-1">Порти UDP PX4 MAVLink за замовчуванням <a class="header-anchor" href="#порти-udp-px4-mavlink-за-замовчуванням" aria-label="Permalink to &quot;Порти UDP PX4 MAVLink за замовчуванням&quot;">​</a></h2><p>By default, PX4 uses commonly established UDP ports for MAVLink communication with ground control stations (e.g. <em>QGroundControl</em>), Offboard APIs (e.g. MAVSDK, MAVROS) and simulator APIs (e.g. Gazebo). Ці порти:</p><ul><li>PX4&#39;s remote UDP Port <strong>14550</strong> is used for communication with ground control stations. Очікується, що GCS прослуховуватиме з&#39;єднання на цьому порту. <em>QGroundControl</em> listens to this port by default.</li><li>PX4&#39;s remote UDP Port <strong>14540</strong> is used for communication with offboard APIs. Очікується, що зовнішні API будуть чекати на з&#39;єднання через цей порт.<div class="info custom-block"><p class="custom-block-title">INFO</p><p>Multi-vehicle simulations use a separate remote port for each instance, allocated sequentially from <code>14540</code> to <code>14549</code> (additional instances all use port <code>14549</code>).</p></div></li></ul><p>:::</p><ul><li>The simulator&#39;s local TCP Port, <strong>4560</strong>, is used for communication with PX4. Симулятор слухає цей порт, і PX4 ініціює TCP-з&#39;єднання з ним.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The ports for the GCS, offboard APIs and simulator are specified by startup scripts. See <a href="./../concept/system_startup">System Startup</a> to learn more.</p></div><h2 id="середовище-симуляціі-sitl" tabindex="-1">Середовище симуляції SITL <a class="header-anchor" href="#середовище-симуляціі-sitl" aria-label="Permalink to &quot;Середовище симуляції SITL&quot;">​</a></h2><p>The diagram below shows a typical SITL simulation environment for any of the supported simulators that use MAVLink (i.e. most external simulators, but not Gazebo or SIH).</p><p><img src="'+a+`" alt="PX4 SITL overview"></p><p>Різні частини системи з&#39;єднуються через протокол UDP і можуть працювати як на одному комп&#39;ютері, так і на іншому комп&#39;ютері в тій самій мережі.</p><ul><li><p>PX4 використовує спеціальний модуль для підключення до локального TCP-порту 4560 симулятора. Simulators then exchange information with PX4 using the <a href="#simulator-mavlink-api">Simulator MAVLink API</a> described above. PX4 на SITL і симулятор можуть працювати як на одному комп&#39;ютері, так і на різних комп&#39;ютерах в одній мережі.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Simulators can also use the <em>uxrce-dds bridge</em> (<a href="./../middleware/uxrce_dds">XRCE-DDS</a>) to directly interact with PX4 (i.e. via <a href="./../middleware/uorb">UORB topics</a> rather than MAVLink). This approach <em>may</em> used by Gazebo Classic for <a href="./../sim_gazebo_classic/multi_vehicle_simulation#build-and-test-xrce-dds">multi-vehicle simulation</a>.</p></div></li></ul><p>:::</p><ul><li><p>PX4 використовує звичайний модуль MAVLink для підключення до наземних станцій і зовнішніх API розробників, таких як MAVSDK або ROS</p><ul><li>Ground stations listen to PX4&#39;s remote UDP port: <code>14550</code></li><li>External developer APIs listen to PX4&#39;s remote UDP port: <code>14540</code>. For multi-vehicle simulations, PX4 sequentially allocates a separate remote port for each instance from <code>14540</code> to <code>14549</code> (additional instances all use port <code>14549</code>).</li></ul></li><li><p>PX4 defines a number of <em>local</em> UDP ports (<code>14580</code>,<code>18570</code>), which are sometimes used when networking with PX4 running in a container or virtual machine. Вони не рекомендуються для &quot;загального&quot; використання і можуть змінюватися в майбутньому.</p></li><li><p>A serial connection may be used to connect <a href="./../config/joystick">Joystick/Gamepad</a> hardware via <em>QGroundControl</em>.</p></li></ul><p>If you use the normal build system SITL <code>make</code> configuration targets (see next section) then both SITL and the Simulator will be launched on the same computer and the ports above will automatically be configured. Ви можете налаштувати додаткові UDP-з&#39;єднання MAVLink та іншим чином змінити середовище моделювання у файлах конфігурації та ініціалізації збірки.</p><h3 id="запуск-створення-симуляціі-sitl" tabindex="-1">Запуск/створення симуляції SITL <a class="header-anchor" href="#запуск-створення-симуляціі-sitl" aria-label="Permalink to &quot;Запуск/створення симуляції SITL&quot;">​</a></h3><p>Система збірки дозволяє дуже легко зібрати і запустити PX4 на SITL, активувати симулятор і з&#39;єднати їх. Синтаксис (спрощений) виглядає наступним чином:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> simulator[_vehicle-model]</span></span></code></pre></div><p>where <code>simulator</code> is <code>gz</code> (for Gazebo), <code>gazebo-classic</code>, <code>jmavsim</code> or some other simulator, and vehicle-model is a particular vehicle type supported by that simulator (<a href="./../sim_gazebo_gz/">Gazebo</a> and <a href="./../sim_jmavsim/">jMAVSim</a> only support multicopters at time of writing, while <a href="./../sim_gazebo_classic/">Gazebo Classic</a> supports many different types).</p><p>Нижче наведено кілька прикладів, і їх набагато більше на окремих сторінках для кожного з симуляторів:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start Gazebo with the x500 multicopter</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start Gazebo Classic with plane</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gazebo-classic_plane</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start Gazebo Classic with iris and optical flow</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gazebo-classic_iris_opt_flow</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start JMavSim with iris (default vehicle model)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jmavsim</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start PX4 with no simulator (i.e. to use your own &quot;custom&quot; simulator)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none_iris</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SIH (headless, zero dependencies)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_airplane</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Use <code>px4_sitl_sih</code> instead of <code>px4_sitl</code> to avoid building Gazebo dependencies.</p></div><p>Симуляцію можна додатково налаштувати за допомогою змінних середовища:</p><ul><li>Any of the <a href="./../advanced_config/parameter_reference">PX4 parameters</a> can be overridden via <code>export PX4_PARAM_{name}={value}</code>. For example changing the estimator: <code>export PX4_PARAM_EKF2_EN=0; export PX4_PARAM_ATT_EN=1</code>.</li></ul><p>The syntax described here is simplified, and there are many other options that you can configure via <em>make</em> - for example, to set that you wish to connect to an IDE or debugger. For more information see: <a href="./../dev_setup/building_px4#px4-make-build-targets">Building the Code &gt; PX4 Make Build Targets</a>.</p><h3 id="simulation_speed" tabindex="-1">Run Simulation Faster than Realtime <a class="header-anchor" href="#simulation_speed" aria-label="Permalink to &quot;Run Simulation Faster than Realtime {#simulation_speed}&quot;">​</a></h3><p>SITL can be run faster or slower than real-time when using Gazebo, Gazebo Classic, jMAVSim, or SIH.</p><p>The speed factor is set using the environment variable <code>PX4_SIM_SPEED_FACTOR</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 SITL and the simulators are run in <em>lockstep</em>, which means that they are locked to run at the same speed, and therefore can react appropriately to sensor and actuator messages. This is what makes it possible to run the simulation at different speeds, and also pause the simulation in order to step through code.</p></div><p>Для додаткової інформації дивіться:</p><ul><li>Gazebo: <a href="./../sim_gazebo_gz/#change-simulation-speed">Change Simulation Speed</a></li><li>Gazebo Classic: <a href="./../sim_gazebo_classic/#change-simulation-speed">Change Simulation Speed</a> and <a href="./../sim_gazebo_classic/#lockstep">Lockstep</a></li><li>jMAVSim: <a href="./../sim_jmavsim/#change-simulation-speed">Change Simulation Speed</a> and <a href="./../sim_jmavsim/#lockstep">Lockstep</a></li><li>SIH: Supports <code>PX4_SIM_SPEED_FACTOR</code> for faster-than-realtime simulation.</li></ul><h3 id="сценаріі-запуску" tabindex="-1">Сценарії запуску <a class="header-anchor" href="#сценаріі-запуску" aria-label="Permalink to &quot;Сценарії запуску&quot;">​</a></h3><p>Scripts are used to control which parameter settings to use or which modules to start. They are located in the <a href="https://github.com/PX4/PX4-Autopilot/tree/main/ROMFS/px4fmu_common/init.d-posix" target="_blank" rel="noreferrer">ROMFS/px4fmu_common/init.d-posix</a> directory, the <code>rcS</code> file is the main entry point. See <a href="./../concept/system_startup">System Startup</a> for more information.</p><h3 id="імітація-збоів-та-відмов-датчиків-обладнання" tabindex="-1">Імітація збоїв та відмов датчиків/обладнання <a class="header-anchor" href="#імітація-збоів-та-відмов-датчиків-обладнання" aria-label="Permalink to &quot;Імітація збоїв та відмов датчиків/обладнання&quot;">​</a></h3><p><a href="./../simulation/failsafes">Simulate Failsafes</a> explains how to trigger safety failsafes like GPS failure and battery drain.</p><h3 id="environment-configuration" tabindex="-1">Environment Configuration <a class="header-anchor" href="#environment-configuration" aria-label="Permalink to &quot;Environment Configuration&quot;">​</a></h3><p>SITL simulation behaviour can be configured using the following environment variables. These can be specified inline, before the <code>make</code> command, or set for the environment using <code>export</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For Gazebo-specific environment variables (such as <code>PX4_GZ_WORLD</code>, <code>PX4_GZ_STANDALONE</code>, etc.), see <a href="./../sim_gazebo_gz/#usage-configuration-options">Gazebo &gt; Usage/Configuration Options</a>.</p></div><ul><li><p><code>PX4_SIM_SPEED_FACTOR</code>: Sets the speed factor to run the simulation at faster or slower than realtime. For example, to run Gazebo simulation at two times the speed factor:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_SIM_SPEED_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span></code></pre></div><p>For more information see <a href="#simulation_speed">Run Simulation Faster than Realtime</a>.</p></li><li><p><code>PX4_PARAM_{name}={value}</code>: Overrides any <a href="./../advanced_config/parameter_reference">PX4 parameter</a> for the simulation session. For example, to switch from EKF2 to the attitude estimator:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_PARAM_EKF2_EN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_PARAM_ATT_EN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div></li><li><p><code>PX4_NET_INTERFACE</code>: Binds all MAVLink connections to a specific network interface (e.g. <code>eth0</code>). This is useful when running simulations in containerized environments (e.g. Docker) or on systems with multiple network interfaces where you need MAVLink traffic to use a particular interface.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_NET_INTERFACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">eth0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span></code></pre></div><p>Or inline with the make command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_NET_INTERFACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">eth0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span></code></pre></div><p>This sets the <code>-n</code> flag on all <code>mavlink start</code> commands in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink" target="_blank" rel="noreferrer">/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink</a>, binding MAVLink to the specified interface. When <code>PX4_NET_INTERFACE</code> is not set, MAVLink binds to all interfaces (default behaviour).</p></li></ul><h2 id="середовище-симуляціі-hitl" tabindex="-1">Середовище симуляції HITL <a class="header-anchor" href="#середовище-симуляціі-hitl" aria-label="Permalink to &quot;Середовище симуляції HITL&quot;">​</a></h2><p>У симуляції з апаратним забезпеченням у контурі (HITL) звичайна прошивка PX4 виконується на реальному обладнані. The HITL Simulation Environment in documented in: <a href="./../simulation/hitl">HITL Simulation</a>.</p><h2 id="інтеграція-джоистиків-геимпада" tabindex="-1">Інтеграція джойстиків/геймпада <a class="header-anchor" href="#інтеграція-джоистиків-геимпада" aria-label="Permalink to &quot;Інтеграція джойстиків/геймпада&quot;">​</a></h2><p><em>QGroundControl</em> desktop versions can connect to a USB Joystick/Gamepad and send its movement commands and button presses to PX4 over MAVLink. Це працює як на SITL, так і на HITL симуляціях, і дозволяє вам безпосередньо керувати симульованим апаратом. Якщо у вас немає джойстика, ви можете керувати апаратом за допомогою екранних віртуальних паличок QGroundControl.</p><p>For setup information see the <em>QGroundControl User Guide</em>:</p><ul><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/joystick.html" target="_blank" rel="noreferrer">Joystick Setup</a></li><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/settings_view/virtual_joystick.html" target="_blank" rel="noreferrer">Virtual Joystick</a></li></ul><h2 id="симуляція-камери" tabindex="-1">Симуляція камери <a class="header-anchor" href="#симуляція-камери" aria-label="Permalink to &quot;Симуляція камери&quot;">​</a></h2><p>PX4 supports capture of both still images and video from within the <a href="./../sim_gazebo_classic/">Gazebo Classic</a> simulated environment. This can be enabled/set up as described in <a href="./../sim_gazebo_classic/#video-streaming">Gazebo Glassic &gt; Video Streaming</a>.</p><p>The simulated camera is a gazebo classic plugin that implements the <a href="https://mavlink.io/en/services/camera.html" target="_blank" rel="noreferrer">MAVLink Camera Protocol</a> . PX4 connects/integrates with this camera in <em>exactly the same way</em> as it would with any other MAVLink camera:</p><ol><li><a href="./../advanced_config/parameter_reference#TRIG_INTERFACE">TRIG_INTERFACE</a> must be set to <code>3</code> to configure the camera trigger driver for use with a MAVLink camera<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In this mode the driver just sends a <a href="https://mavlink.io/en/messages/common.html#CAMERA_TRIGGER" target="_blank" rel="noreferrer">CAMERA_TRIGGER</a> message whenever an image capture is requested. For more information see <a href="./../camera/fc_connected_camera">Cameras Connected to Flight Controller Outputs</a>.</p></div></li></ol><p>::: 2. PX4 повинен перенаправляти всі команди камери між GCS і (симулятором) MAVLink Camera. You can do this by starting <a href="./../modules/modules_communication#mavlink">MAVLink</a> with the <code>-f</code> flag as shown, specifying the UDP ports for the new connection.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mavlink</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14558</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14530</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> camera</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>More than just the camera MAVLink messages will be forwarded, but the camera will ignore those that it doesn&#39;t consider relevant.</p></div><p>Інші симулятори можуть використовувати такий самий підхід для реалізації підтримки камери.</p><h2 id="запуск-симуляціі-на-віддаленому-сервері" tabindex="-1">Запуск симуляції на віддаленому сервері <a class="header-anchor" href="#запуск-симуляціі-на-віддаленому-сервері" aria-label="Permalink to &quot;Запуск симуляції на віддаленому сервері&quot;">​</a></h2><p>Симулятор можна запустити на одному комп&#39;ютері, а доступ до нього отримати з іншого комп&#39;ютера в тій же мережі (або в іншій мережі з відповідною маршрутизацією). Це може бути корисно, наприклад, якщо ви хочете протестувати програму для безпілотника, що працює на реальному комп&#39;ютері-компаньйоні на фоні змодельованого транспортного засобу.</p><p>Це не працює &quot;з коробки&quot;, оскільки PX4 за замовчуванням не маршрутизує пакети на зовнішні інтерфейси (щоб уникнути спаму в мережі та втручання різних симуляцій одна в одну). Замість цього він спрямовує трафік всередину - на &quot;localhost&quot;.</p><p>Існує декілька способів зробити UDP-пакети доступними на зовнішніх інтерфейсах, як описано нижче.</p><h3 id="використання-mavlink-router" tabindex="-1">Використання MAVLink Router <a class="header-anchor" href="#використання-mavlink-router" aria-label="Permalink to &quot;Використання MAVLink Router&quot;">​</a></h3><p>The <a href="https://github.com/mavlink-router/mavlink-router" target="_blank" rel="noreferrer">mavlink-router</a> can be used to route packets from localhost to an external interface.</p><p>To route packets between SITL running on one computer (sending MAVLink traffic to localhost on UDP port 14550), and QGC running on another computer (e.g. at address <code>10.73.41.30</code>) you could:</p><ul><li><p>Start <em>mavlink-router</em> with the following command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mavlink-routerd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.73.41.30:14550</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:14550</span></span></code></pre></div></li><li><p>Use a <em>mavlink-router</em> conf file.</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[UdpEndpoint QGC]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = Normal</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 10.73.41.30</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 14550</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[UdpEndpoint SIM]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = Eavesdropping</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 14550</span></span></code></pre></div></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>More information about <em>mavlink-router</em> configuration can be found <a href="https://github.com/mavlink-router/mavlink-router#running" target="_blank" rel="noreferrer">here</a>.</p></div><h3 id="увімкнення-трансляціі-udp" tabindex="-1">Увімкнення трансляції UDP <a class="header-anchor" href="#увімкнення-трансляціі-udp" aria-label="Permalink to &quot;Увімкнення трансляції UDP&quot;">​</a></h3><p>The <a href="./../modules/modules_communication#mavlink_usage">mavlink module</a> routes to <em>localhost</em> by default, but you can enable UDP broadcasting of heartbeats using its <code>-p</code> option. Any remote computer on the network can then connect to the simulator by listening to the appropriate port (i.e. 14550 for <em>QGroundControl</em>).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>UDP broadcasting provides a simple way to set up the connection when there is only one simulation running on the network. Do not use this approach if there are multiple simulations running on the network (you might instead <a href="#enable-streaming-to-specific-address">publish to a specific address</a>).</p></div><p>This should be done in an appropriate configuration file where <code>mavlink start</code> is called. For example: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink" target="_blank" rel="noreferrer">/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink</a>.</p><h3 id="увімкнення-стрімінгу-на-певну-адресу" tabindex="-1">Увімкнення стрімінгу на певну адресу <a class="header-anchor" href="#увімкнення-стрімінгу-на-певну-адресу" aria-label="Permalink to &quot;Увімкнення стрімінгу на певну адресу&quot;">​</a></h3><p>The <a href="./../modules/modules_communication#mavlink_usage">mavlink module</a> routes to <em>localhost</em> by default, but you can specify an external IP address to stream to using its <code>-t</code> option. The specified remote computer can then connect to the simulator by listening to the appropriate port (i.e. 14550 for <em>QGroundControl</em>).</p><p>This should be done in various configuration files where <code>mavlink start</code> is called. For example: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink" target="_blank" rel="noreferrer">/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink</a>.</p><h3 id="тунелювання-по-ssh" tabindex="-1">Тунелювання по SSH <a class="header-anchor" href="#тунелювання-по-ssh" aria-label="Permalink to &quot;Тунелювання по SSH&quot;">​</a></h3><p>Тунелювання SSH є гнучким варіантом, оскільки комп&#39;ютер для моделювання та система, що його використовує, не обов&#39;язково повинні знаходитися в одній мережі.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You might similarly use VPN to provide a tunnel to an external interface (on the same network or another network).</p></div><p>Одним із способів створення тунелю є використання параметрів тунелювання SSH. The tunnel itself can be created by running the following command on <em>localhost</em>, where <code>remote.local</code> is the name of a remote computer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 14551:localhost:14551</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote.local</span></span></code></pre></div><p>UDP-пакети потрібно перетворити на TCP-пакети, щоб їх можна було перенаправляти через SSH. The <a href="https://en.wikipedia.org/wiki/Netcat" target="_blank" rel="noreferrer">netcat</a> utility can be used on both sides of the tunnel - first to convert packets from UDP to TCP, and then back to UDP at the other end.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>QGC must be running before executing <em>netcat</em>.</p></div><p>On the <em>QGroundControl</em> computer, UDP packet translation may be implemented by running following commands:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkfifo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/tcp2udp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lvp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14551</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/tcp2udp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> netcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14550</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/tcp2udp</span></span></code></pre></div><p>Команда на стороні симулятора тунелю SSH:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkfifo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/udp2tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lvup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14550</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/udp2tcp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> netcat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14551</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/udp2tcp</span></span></code></pre></div><p>The port number <code>14550</code> is valid for connecting to QGroundControl or another GCS, but should be adjusted for other endpoints (e.g. developer APIs etc.).</p><p>The tunnel may in theory run indefinitely, but <em>netcat</em> connections may need to be restarted if there is a problem.</p><p>The <a href="https://raw.githubusercontent.com/ThunderFly-aerospace/sitl_gazebo/autogyro-sitl/scripts/QGC_remote_connect.bash" target="_blank" rel="noreferrer">QGC_remote_connect.bash</a> script can be run on the QGC computer to automatically setup/run the above instructions. Симуляція вже має бути запущена на віддаленому сервері, і ви повинні мати доступ по SSH до цього сервера.</p>`,107)])])}const b=i(r,[["render",l]]);export{g as __pageData,b as default};
